<body>
  <main id="app"></main>
  <script type="module">
    const app = document.querySelector('#app');
    const esc = (value) => String(value).replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);

    async function loadProjects() {
      const response = await fetch('/api/projects');
      if (!response.ok) throw new Error('Could not load projects');
      return response.json();
    }

    async function showList(error = '', selectedFilter = 'Active') {
      app.innerHTML = `<h1>Workboard</h1>
        ${error ? `<p class="alert" role="alert">${esc(error)}</p>` : ''}
        <form id="create-form">
          <input id="project-name" name="name" aria-label="Project name" placeholder="Project name">
          <button type="submit">Create project</button>
        </form>
        <div class="filters"><label for="project-filter">Project filter</label><select id="project-filter"><option>Active</option><option>Archived</option></select></div>
        <section class="rows" aria-label="Projects" id="project-list"></section>`;
      const list = app.querySelector('#project-list');
      const filter = app.querySelector('#project-filter');
      filter.value = selectedFilter;
      async function renderProjects() {
        list.replaceChildren();
        for (const project of await loadProjects()) {
          if ((filter.value === 'Archived') !== project.archived) continue;
          const row = document.createElement('div');
          row.dataset.testid = 'project-row';
          const details = document.createElement('div');
          details.className = 'project-details';
          const name = document.createElement('span');
          name.textContent = project.name;
          const summary = document.createElement('span');
          summary.dataset.testid = 'project-summary';
          summary.textContent = `${project.completedCount}/${project.totalCount} completed`;
          details.append(name, summary);
          const actions = document.createElement('div');
          actions.className = 'project-actions';
          const open = document.createElement('button');
          open.type = 'button'; open.textContent = 'Open project';
          open.addEventListener('click', () => navigate(`/projects/${project.id}`));
          const stateButton = document.createElement('button');
          stateButton.type = 'button';
          stateButton.textContent = project.archived ? 'Restore project' : 'Archive project';
          stateButton.addEventListener('click', async () => {
            await fetch(`/api/projects/${project.id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ archived: !project.archived }) });
            await renderProjects();
          });
          actions.append(open, stateButton);
          row.append(details, actions);
          list.append(row);
        }
      }
      filter.addEventListener('change', renderProjects);
      await renderProjects();
      app.querySelector('#create-form').addEventListener('submit', async (event) => {
        event.preventDefault();
        const name = app.querySelector('#project-name').value.trim();
        if (!name) return showList('Project name is required', filter.value);
        const response = await fetch('/api/projects', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name }) });
        if (!response.ok) return showList('Could not create project');
        showList('', filter.value);
      });
    }

    async function showProject(id) {
      const response = await fetch(`/api/projects/${encodeURIComponent(id)}`);
      if (!response.ok) { history.replaceState({}, '', '/'); return showList(); }
      const project = await response.json();
      app.innerHTML = `<button class="back" type="button">Projects</button><h1>${esc(project.name)}</h1>
        ${project.archived ? '<p>Archived project</p>' : ''}
        <p id="task-alert" class="alert" role="alert" hidden></p>
        <form id="task-form"><input id="task-title" aria-label="Task title" placeholder="Task title" ${project.archived ? 'disabled' : ''}><button type="submit" ${project.archived ? 'disabled' : ''}>Create task</button></form>
        <div class="filters"><label for="task-filter">Task filter</label><select id="task-filter"><option>All</option><option>Open</option><option>Completed</option></select></div>
        <section class="rows" id="task-list" aria-label="Tasks"></section>`;
      app.querySelector('.back').addEventListener('click', () => navigate('/'));
      const list = app.querySelector('#task-list');
      const filter = app.querySelector('#task-filter');
      const alert = app.querySelector('#task-alert');
      async function renderTasks() {
        const tasksResponse = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks`);
        const tasks = await tasksResponse.json();
        list.replaceChildren();
        for (const task of tasks) {
          if (filter.value === 'Open' && task.completed) continue;
          if (filter.value === 'Completed' && !task.completed) continue;
          const row = document.createElement('div');
          row.className = `task-row${task.completed ? ' completed' : ''}`;
          row.dataset.testid = 'task-row';
          const checkbox = document.createElement('input');
          checkbox.type = 'checkbox';
          checkbox.checked = task.completed;
          checkbox.disabled = project.archived;
          checkbox.setAttribute('aria-label', `Complete ${task.title}`);
          checkbox.addEventListener('change', async () => {
            await fetch(`/api/tasks/${task.id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ completed: checkbox.checked }) });
            renderTasks();
          });
          const title = document.createElement('span');
          title.textContent = task.title;
          row.append(checkbox, title);
          list.append(row);
        }
      }
      filter.addEventListener('change', renderTasks);
      app.querySelector('#task-form').addEventListener('submit', async (event) => {
        event.preventDefault();
        const title = app.querySelector('#task-title').value.trim();
        if (!title) { alert.textContent = 'Task title is required'; alert.hidden = false; return; }
        const created = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title }) });
        if (!created.ok) { alert.textContent = 'Could not create task'; alert.hidden = false; return; }
        alert.hidden = true;
        app.querySelector('#task-title').value = '';
        await renderTasks();
      });
      await renderTasks();
    }

    function navigate(path) {
      history.pushState({}, '', path);
      render();
    }
    function render() {
      const match = location.pathname.match(/^\/projects\/(\d+)$/);
      return match ? showProject(match[1]) : showList();
    }
    window.addEventListener('popstate', render);
    render();
  </script>
